///////////////////////FUNCTION LOAD GLOSSARY DEFINITION (Joao)///////////////////////////////////////

function loadglossarydefinition(a, b) {
  var id = a;
  var definition = b;

  $.getJSON("/library/glossary/glossary.json", function (data) {
    var def = "";

    console.log(data);
    $.each(data, function (key, val) {
      if (val.GlossaryID == id) {
        def +=
          '<a data-container="body" data-content="' +
          val.EnglishDefinition +
          '" data-original-title="' +
          val.EnglishWord +
          '" data-placement="bottom" data-toggle="popover" title="">' +
          definition +
          "</a>";
      }
    });

    $("#def" + id + "").append(def);
  });
  document.write('<span id="def' + id + '"></span>');
}
///////////////////////////////////NEW VERSION FOR SPANS///////////////////////

function glossdefid() {
  $.getJSON("/library/glossary/glossary.json", function (data) {
    var def = "";
    var id = "";
    var definition = "";
    var word = "";

    console.log(data);
    $.each(data, function (key, val) {
      id = val.GlossaryID;
      definition = val.EnglishDefinition;
      word = val.EnglishWord;

      $(".glossId_" + id + "").attr("data-content", definition);
      $(".glossId_" + id + "").attr("data-original-title", word);
      $(".glossId_" + id + "").attr("data-toggle", "popover");
      $(".glossId_" + id + "").attr("data-placement", "bottom");
    });
  });
}

